const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function mountVirtualSystems(container,{api,summary,notice,onPremise,onAdvance,offset=0,exceptionCode="",invoiceOffset=0}){
  container.innerHTML='<div class="panel"><h2>Virtual Systems</h2><p>Opening the dedicated billing and receivables recipients…</p></div>';
  const marker=Symbol();container._virtualMarker=marker;
  try{
    const state=await api('virtual-systems?offset='+offset+'&invoiceOffset='+invoiceOffset+(exceptionCode?'&exceptionCode='+encodeURIComponent(exceptionCode):''));if(container._virtualMarker!==marker||!container.isConnected)return;
    const disabled=!summary||!state.configured?'disabled':'';
    container.innerHTML=`<div class="panel"><h2>Actual Virtual Systems recipients</h2><p>${state.configured?'The separately installed Virtual Systems engine is configured. This town uses its own billing and receivables stores.':'This runtime has no Virtual Systems installation configured. Set ATLAS_VIRTUAL_SYSTEMS_ROOT on the server to the existing private checkout.'}</p><p class="subtle">${esc(state.tariffPolicy)}</p><p class="subtle">World days are advanced manually. The shared scheduler and automatic field dispatch are not enabled.</p><div class="actions"><button data-vs-advance ${disabled}>Advance one day</button><button data-vs="initialize" ${disabled}>${state.initialized?'Check recipient setup':'Initialize town recipients'}</button><button data-vs="ingest" ${disabled||(!state.initialized?'disabled':'')}>Deliver observations to MDM</button><label>Start<input id="vs-start" type="date" value="${esc(state.nextPeriodStart||'2026-01-01')}"></label><label>End (exclusive)<input id="vs-end" type="date" value="${esc(state.through||summary?.state.through||'2026-01-08')}"></label><button data-vs="run" ${disabled||(!state.initialized?'disabled':'')}>Bill, invoice & post receivables</button><button data-vs="invoice-eligible" ${disabled||(!state.initialized?'disabled':'')}>Invoice eligible accounts</button></div><p class="subtle">Eligible-account invoicing keeps incomplete accounts on hold and resumes from already issued invoices.</p>${state.lastBillingBatch?`<p>Last batch ${esc(state.lastBillingBatch.start)} to ${esc(state.lastBillingBatch.end)}: ${state.lastBillingBatch.invoicedAccounts.toLocaleString()} accounts invoiced, ${state.lastBillingBatch.eligibleAccounts.toLocaleString()} ready to invoice, ${state.lastBillingBatch.heldAccounts.toLocaleString()} held. ${state.lastBillingBatch.billedContracts.toLocaleString()} of ${state.lastBillingBatch.contracts.toLocaleString()} contracts billed; ${state.lastBillingBatch.heldContracts.toLocaleString()} require readings or review.</p>`:''}<p id="vs-result" role="status"></p></div>${state.initialized?`<div class="cards">${Object.entries(state.counts).map(([key,value])=>`<div class="card"><span>${esc(key==='exceptions'?'Exception history':key)}</span><strong>${Number(value).toLocaleString()}</strong></div>`).join('')}</div><div class="panel"><h2>Independent receivables trial balance</h2>${Object.entries(state.trialBalance?.totals||{}).map(([currency,total])=>`<div class="record-row"><span>${esc(currency)} · ${total.balanced?'Balanced':'Out of balance'}</span><b>Debit ${(total.debit_minor/100).toFixed(2)} / Credit ${(total.credit_minor/100).toFixed(2)}</b></div>`).join('')||'<p>No invoices posted yet.</p>'}<details><summary>Ledger evidence</summary><pre>${esc(JSON.stringify(state.trialBalance,null,2))}</pre></details><p>Observations delivered through ${esc(state.receivedThrough)}. Missing observations retained: ${esc(state.missingObservations)}.</p></div><div class="panel"><h2>Invoices</h2><div class="actions"><button id="vs-invoice-prev" ${invoiceOffset===0?'disabled':''}>Newer invoices</button><span>${state.counts.invoices?invoiceOffset+1:0}–${Math.min(invoiceOffset+50,state.counts.invoices)} of ${state.counts.invoices}</span><button id="vs-invoice-next" ${invoiceOffset+50>=state.counts.invoices?'disabled':''}>Older invoices</button></div>${state.invoices.map(i=>`<div class="record-row"><span><code>${esc(i.id)}</code><br>${esc(i.account_id)} · ${esc(i.cycle_id)}</span><strong>${(i.total_minor/100).toFixed(2)} ${esc(i.currency)}</strong></div>`).join('')||'<p>No invoices. Complete coverage and resolve held consumption before invoicing.</p>'}</div><div class="panel"><h2>Open billing exceptions</h2><label>Exception filter<select id="vs-filter"><option value="">All open exceptions</option><option value="HIGH_CONSUMPTION" ${exceptionCode==='HIGH_CONSUMPTION'?'selected':''}>Consumption awaiting review</option></select></label>${state.exceptions.map(e=>`<div class="panel"><b>${esc(e.code)}</b><p>${esc(e.message)}</p><code>${esc(e.subject)}</code>${e.premiseId?`<button data-vs-premise="${esc(e.premiseId)}">Open property & field work</button>`:''}${e.code==='HIGH_CONSUMPTION'?`<form data-resolve="${esc(e.id)}"><label>Review reason<input name="note" required placeholder="Explain why the observed consumption is valid"></label><button>Release reviewed consumption</button></form>`:''}</div>`).join('')||'<p>No open exceptions.</p>'}</div>`:''}`;
    if(state.initialized){container.insertAdjacentHTML('beforeend',`<div class="actions"><button id="vs-prev" ${offset===0?'disabled':''}>Newer exceptions</button><span>${state.exceptionTotal?offset+1:0}–${Math.min(offset+50,state.exceptionTotal||0)} of ${state.exceptionTotal||0} open exceptions</span><button id="vs-next" ${offset+50>=(state.exceptionTotal||0)?'disabled':''}>Older exceptions</button></div>`);container.querySelector('#vs-prev').onclick=()=>mountVirtualSystems(container,{api,summary,notice,onPremise,onAdvance,offset:Math.max(0,offset-50),exceptionCode,invoiceOffset});container.querySelector('#vs-next').onclick=()=>mountVirtualSystems(container,{api,summary,notice,onPremise,onAdvance,offset:offset+50,exceptionCode,invoiceOffset});container.querySelector('#vs-filter').onchange=e=>mountVirtualSystems(container,{api,summary,notice,onPremise,onAdvance,offset:0,exceptionCode:e.target.value,invoiceOffset});}
    if(state.initialized){container.querySelector('#vs-invoice-prev').onclick=()=>mountVirtualSystems(container,{api,summary,notice,onPremise,onAdvance,offset,exceptionCode,invoiceOffset:Math.max(0,invoiceOffset-50)});container.querySelector('#vs-invoice-next').onclick=()=>mountVirtualSystems(container,{api,summary,notice,onPremise,onAdvance,offset,exceptionCode,invoiceOffset:invoiceOffset+50});}
    container.querySelector('[data-vs-advance]').onclick=()=>onAdvance?.();
    container.querySelectorAll('[data-vs-premise]').forEach(button=>button.onclick=()=>onPremise?.(button.dataset.vsPremise));
    container.querySelectorAll('[data-vs]').forEach(button=>button.onclick=async()=>{
      const which=button.dataset.vs,body={townId:summary.town.id};if(which==='run'||which==='invoice-eligible')Object.assign(body,{start:container.querySelector('#vs-start').value,end:container.querySelector('#vs-end').value});
      container.querySelectorAll('button').forEach(b=>b.disabled=true);container.querySelector('#vs-result').textContent='Processing the saved town. Large towns can take several minutes…';
      try{const result=await api('virtual-systems/'+which,body);if(container._virtualMarker!==marker)return;notice(result.invoiceBlocked||`${which} completed in Virtual Systems.`);await mountVirtualSystems(container,{api,summary,notice,onPremise,onAdvance,offset,exceptionCode,invoiceOffset});}catch(e){if(container._virtualMarker!==marker)return;notice(e.message);container.querySelector('#vs-result').textContent=e.message;container.querySelectorAll('button').forEach(b=>b.disabled=false);}
    });
    container.querySelectorAll('[data-resolve]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();form.querySelector('button').disabled=true;try{await api('virtual-systems/resolve',{townId:summary.town.id,exceptionId:form.dataset.resolve,note:form.elements.note.value});if(container._virtualMarker!==marker)return;await mountVirtualSystems(container,{api,summary,notice,onPremise,onAdvance,offset,exceptionCode,invoiceOffset});}catch(error){notice(error.message);form.querySelector('button').disabled=false;}});
  }catch(e){if(container._virtualMarker!==marker)return;container.innerHTML=`<div class="panel"><h2>Virtual Systems unavailable</h2><p>${esc(e.message)}</p></div>`;}
}
